// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 burnValue, uint256 initialSupply) public {
        // Restrict burnValue to be <= initialSupply to satisfy the require in burn
        vm.assume(initialSupply > 0);
        burnValue = bound(burnValue, 0, initialSupply);

        // Mint initial supply to owner (msg.sender is test contract)
        c.mintToken(address(this), initialSupply);
        uint256 totalSupplyBefore = c.totalSupply();

        // Call burn
        c.burn(burnValue);

        // After burn, totalSupply must have decreased exactly by burnValue
        assertTrue(c.totalSupply() == totalSupplyBefore - burnValue);
    }
}

