pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 initialSupply, uint256 burnAmount) public {
        // Deploy with any token name and symbol to avoid string conversion issue
        c = new C(0, "", "");
        string memory name = c.name();
        string memory symbol = c.symbol();

        // First we need to give the owner some tokens to burn by minting
        // Since deploy gives totalSupply to owner, we start from that
        uint256 supplyBeforeBurn = c.totalSupply();

        // Transfer some tokens to a test account, or use mint to set up a balance
        // To keep it simple, we just use the default owner which has totalSupply
        // We'll bound burnAmount to ensure it's within the balance
        vm.assume(burnAmount <= supplyBeforeBurn);

        // Call burn and capture return value
        (bool success) = address(c).call(abi.encodeWithSelector(c.burn.selector, burnAmount));

        // Get current totalSupply
        uint256 supplyAfterBurn = c.totalSupply();

        // The invariant: if burn succeeded, totalSupply decreased by exactly burnAmount
        // If burn failed (because no tokens or not owner), totalSupply unchanged
        assertTrue(
            (success && supplyAfterBurn + burnAmount == supplyBeforeBurn) ||
            (!success && supplyAfterBurn == supplyBeforeBurn)
        );
    }
}

