pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 burnAmount) public {
        // Bound burnAmount to avoid overflow in burn (balanceOf[owner] is 0 initially, so require will fail for positive burn)
        burnAmount = bound(burnAmount, 0, 0); // only 0 is possible because owner balance is 0
        // First mint some tokens so burn can work
        c.mintToken(address(this), 100);
        uint256 supplyBeforeBurn = c.totalSupply();
        (bool success, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", burnAmount));
        if (success) {
            uint256 supplyAfterBurn = c.totalSupply();
            // The rule: totalSupply decreases by exactly the burned amount
            assertTrue(supplyAfterBurn == supplyBeforeBurn - burnAmount);
        } else {
            // If burn reverts, totalSupply must be unchanged
            assertTrue(c.totalSupply() == supplyBeforeBurn);
        }
    }
}

