import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address burner, uint256 amountToMint, uint256 burnAmount) public {
        vm.assume(burner != address(0));
        vm.assume(burnAmount <= type(uint256).max / 2);
        vm.assume(amountToMint <= type(uint256).max / 2);

        // Set up some balance for burner
        vm.prank(address(0xdead));
        c.freezeAccount(burner, false);
        vm.prank(c.owner());
        c.mintToken(burner, amountToMint);
        vm.prank(burner);

        // Get pre-burn totalSupply
        uint256 preTotalSupply = c.totalSupply();

        // Burn
        c.burn(burnAmount);

        // Get post-burn totalSupply
        uint256 postTotalSupply = c.totalSupply();

        // Assert: post-burn totalSupply equals pre-burn totalSupply minus burnAmount
        assertTrue(postTotalSupply == preTotalSupply - burnAmount);
    }
}

