pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 burnAmount, address caller) public {
        vm.assume(caller != address(0));
        vm.assume(burnAmount > 0 && burnAmount <= 1e30);
        vm.assume(burnAmount <= type(uint256).max / 1e18);

        uint256 initialSupply = c.totalSupply();
        vm.deal(address(c), 0);

        // Mint tokens to caller first so they have balance to burn
        // Using a separate address for minting
        address minter = address(0xDEAD);
        vm.prank(minter, minter);
        try c.mintToken(minter, initialSupply + 1e18) {} catch {}

        // Transfer some tokens to caller
        vm.prank(minter);
        c.transfer(caller, burnAmount * 2);

        uint256 callersBalanceBefore = c.balanceOf(caller);
        uint256 totalSupplyBefore = c.totalSupply();

        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", burnAmount));

        if (!success) {
            // If burn fails, nothing changes
            assertTrue(c.balanceOf(caller) == callersBalanceBefore && c.totalSupply() == totalSupplyBefore);
        } else {
            // After burn: totalSupply decreased by burnAmount, balanceOf decreased by burnAmount
            assertTrue(c.totalSupply() == totalSupplyBefore - burnAmount && c.balanceOf(caller) == callersBalanceBefore - burnAmount);
        }
    }
}

