contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address burner, uint256 amount, address other) public {
        vm.assume(other != address(0) && other != burner);
        vm.assume(amount > 0 && amount <= type(uint256).max / 1e18);
        vm.prank(burner);
        c.mintToken(burner, 1e18 * 100);
        uint256 beforeSupply = c.totalSupply();
        uint256 beforeOther = c.balanceOf(other);
        vm.prank(burner);
        (bool success, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", amount));
        if (!success) {
            assertTrue(beforeOther == c.balanceOf(other) && beforeSupply == c.totalSupply());
        } else {
            assertTrue(beforeOther == c.balanceOf(other));
        }
    }
}

