pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address caller, uint256 burnAmount, address other, uint256 mintAmount) public {
        vm.assume(caller != address(0) && other != address(0) && caller != other);
        vm.assume(burnAmount > 0 && burnAmount <= type(uint256).max);
        vm.assume(mintAmount > 0 && mintAmount <= type(uint256).max / 2);

        // Pre-mint to the caller to ensure they have tokens to burn
        vm.prank(c.owner());
        c.mintToken(caller, mintAmount);

        // Record balances before burn
        uint256 callerBalanceBefore = c.balanceOf(caller);
        uint256 otherBalanceBefore = c.balanceOf(other);
        uint256 totalSupplyBefore = c.totalSupply();

        // Perform burn with the caller account
        vm.prank(caller);
        uint256 actualBurn = burnAmount > callerBalanceBefore ? callerBalanceBefore : burnAmount;
        (bool success, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", actualBurn));

        if (success) {
            // Read state after burn
            uint256 callerBalanceAfter = c.balanceOf(caller);
            uint256 otherBalanceAfter = c.balanceOf(other);
            uint256 totalSupplyAfter = c.totalSupply();

            // Rule: total supply decrease equals sum of all balance decreases
            uint256 callerDecrease = callerBalanceBefore - callerBalanceAfter;
            uint256 otherChange = otherBalanceBefore >= otherBalanceAfter ? 
                otherBalanceBefore - otherBalanceAfter : 0;
            uint256 totalDecrease = totalSupplyBefore - totalSupplyAfter;

            assertTrue(totalDecrease == callerDecrease + otherChange, "total supply decrease != sum of balance decreases");
        }
    }
}

