pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address caller, address target, uint256 mintAmount, uint256 burnAmount) public {
        vm.assume(caller != address(0) && target != address(0));
        vm.assume(mintAmount < 1e30 && burnAmount < 1e30);

        // First mint to target
        vm.prank(c.owner());
        c.mintToken(target, mintAmount);

        // Then caller burns
        vm.prank(caller);
        c.burn(burnAmount);

        // Rule: totalSupply should equal sum of all balances
        // Since we only have mintToken and burn, and initial totalSupply=0, balances of non-owners are 0
        // After mint: target gets mintAmount, totalSupply increases by mintAmount
        // After burn: caller's balance decreases by burnAmount, totalSupply decreases by burnAmount
        // So: totalSupply = ownerBalance + targetBalance (others are 0)
        uint256 ownerBalance = c.balanceOf(c.owner());
        uint256 targetBalance = c.balanceOf(target);
        uint256 totalSupply = c.totalSupply();

        assertTrue(totalSupply == ownerBalance + targetBalance, "Total supply should equal sum of all balances");
    }
}

